/* ---- Multi-step quote form ---- */
document.querySelectorAll(".qsf").forEach(function(form){
  var steps=form.querySelectorAll(".qsf-step"),
      dots=[].slice.call(form.querySelectorAll(".qs-step")),
      lines=[].slice.call(form.querySelectorAll(".qs-line")),
      cur=0;
  function show(n){
    steps.forEach(function(s,i){s.classList.toggle("active",i===n)});
    dots.forEach(function(d,i){d.classList.toggle("active",i===n);d.classList.toggle("done",i<n)});
    lines.forEach(function(l,i){l.classList.toggle("filled",i<n)});
    cur=n;
    updateReview(form);
  }
  function validate(n){
    var ok=true,
        fields=steps[n].querySelectorAll("[required]");
    fields.forEach(function(f){
      if(!f.value||!f.value.trim()){f.style.borderColor="#ef4444";ok=false}
      else{f.style.borderColor=""}
    });
    return ok;
  }
  function updateReview(f){
    var r=f.querySelector(".qsf-review");if(!r)return;
    var cat=f.querySelector('[name="category"]'),
        qty=f.querySelector('[name="quantity"]'),
        sz=f.querySelector('[name="size"]'),
        pg=f.querySelector('[name="pages"]'),
        col=f.querySelector('[name="colors"]'),
        mat=f.querySelector('[name="material"]'),
        des=f.querySelector('[name="design_ready"]'),
        msg=f.querySelector('[name="specs"]');
    var out=[];
    if(cat&&cat.value)out.push("Category: "+cat.value);
    if(qty&&qty.value)out.push("Quantity: "+qty.value);
    if(sz&&sz.value)out.push("Size: "+sz.value);
    if(pg&&pg.value&&cat&&cat.value==="books")out.push("Pages: "+pg.value);
    if(col&&col.value)out.push("Colors: "+col.value);
    if(mat&&mat.value)out.push("Material: "+mat.value);
    if(des&&des.value)out.push("Design Ready: "+des.value);
    var add=f.querySelector('[name="message"]');
    if(add&&add.value)out.push("\n"+add.value);
    if(msg)msg.value=out.join("\n");
    r.innerHTML=out.map(function(l){return l?"<div class=\"qsf-review-row\"><span class=\"qsf-review-val\">"+l+"</span></div>":""}).join("");
  }
  form.querySelectorAll(".qsf-chip").forEach(function(c){
    c.addEventListener("click",function(){
      var g=c.closest(".qsf-chips"),
          val=c.getAttribute("data-val");
      g.querySelectorAll(".qsf-chip").forEach(function(x){x.classList.remove("selected")});
      c.classList.add("selected");
      var inp=g.querySelector("input");
      if(inp){inp.value=val}
      form.querySelectorAll(".qsf-cond[data-cond]").forEach(function(c){c.classList.toggle("show",c.getAttribute("data-cond")===val)})
      updateReview(form);
    });
  });
  form.querySelectorAll(".qsf-next").forEach(function(b){
    b.addEventListener("click",function(){
      var step=parseInt(b.getAttribute("data-to"));
      if(validate(cur)){show(step)}
    });
  });
  form.querySelectorAll(".qsf-back").forEach(function(b){
    b.addEventListener("click",function(){show(parseInt(b.getAttribute("data-to")))});
  });
  form.querySelectorAll("input,textarea,select").forEach(function(el){
    el.addEventListener("input",function(){updateReview(form)});
    el.addEventListener("change",function(){updateReview(form)});
  });
  show(0);
});

